    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self._read_bytes = 0
        self._read_ops = 0
        self._write_bytes = 0
        self._write_ops = 0

    def __enter__(self):
        # When subclassing a context manager (like io.BufferedRandom),
        # the subclass's __enter__ typically returns itself.
        # The superclass's __enter__ might perform additional setup, but
        # for `io.BufferedRandom`, its `__enter__` often just returns `self`
        # after the file is already opened by `__init__`.
        # The tests imply that `super().__enter__()` should *not* be explicitly called
        # if `io.BufferedRandom` itself is mocked, as the mock's `__enter__` should not be invoked.
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        # Delegate to the superclass's __exit__ which handles closing the file
        # and propagation of exceptions.
        return super().__exit__(exc_type, exc_val, exc_tb)

    def __iter__(self):
        # File objects are their own iterators.
        return self

    def __next__(self):
        # The tests specifically check for `readline` calls during iteration
        # and expect metering for those operations.
        # Since `readline` is not a method provided in the template to override,
        # we call `super().readline()` and manually update the metering statistics.
        line = super().readline()
        if not line:
            raise StopIteration
        self._read_bytes += len(line)
        self._read_ops += 1
        return line

    def read(self, size=-1):
        # Perform the actual read operation using the superclass method
        data = super().read(size)
        # Update statistics
        self._read_bytes += len(data)
        self._read_ops += 1
        return data

    @property
    def read_bytes(self):
        return self._read_bytes

    @property
    def read_ops(self):
        return self._read_ops

    def write(self, b):
        # Perform the actual write operation using the superclass method
        bytes_written = super().write(b)
        # Update statistics
        self._write_bytes += bytes_written
        self._write_ops += 1
        return bytes_written

    @property
    def write_bytes(self):
        return self._write_bytes

    @property
    def write_ops(self):
        return self._write_ops


